// Compile a compact context for the model from yesterday's data.
const ymd = (d) => d.toISOString().slice(0,10);
const y = new Date(Date.now() - 86400000);
const yKey = ymd(y);
const metrics = $('Read Daily Metrics').all().map(i => i.json);
const bugs = $('Read Bugs').all().map(i => i.json);
const feedback = $('Read Feedback').all().map(i => i.json);
const content = $('Read Content Queue').all().map(i => i.json);
const yRow = metrics.find(r => String(r['Date']).slice(0,10) === yKey) || {};
const openBugs = bugs.filter(b => ['Open','In Progress'].includes(b['Status']));
const recentFeedback = feedback.slice(-15);
const published = content.filter(c => c['Status']==='Published');
const context = {
  yesterday: yKey,
  installs: yRow['Installs'] || 0,
  paidConversions: yRow['Paid Conversions'] || 0,
  trialsStarted: yRow['Trials Started'] || 0,
  cancellations: yRow['Cancellations'] || 0,
  sparkyMessages: yRow['Sparky Messages'] || 0,
  contentPublishedYesterday: published.filter(c => String(c['Publish Date']).slice(0,10)===yKey).length,
  openBugCount: openBugs.length,
  criticalBugs: openBugs.filter(b => ['Critical','High'].includes(b['Severity'])).map(b => b['Description']).slice(0,5),
  recentFeedback: recentFeedback.map(f => ({ category: f['Category'], text: String(f['Raw Text']||'').slice(0,160) }))
};
return [{ json: { context, model: $('Config').item.json.BRIEF_MODEL, approvalUrl: $('Config').item.json.APPROVAL_WEBHOOK_URL } }];

// Parse model JSON and format a human-readable brief.
let raw = $json.content?.[0]?.text || '{}';
let data;
try { data = JSON.parse(raw); } catch (e) {
  const m = raw.match(/\{[\s\S]*\}/); data = m ? JSON.parse(m[0]) : { summary: raw, priorities: [], hooks: [] };
}
const lines = [];
lines.push('*SparkConnect Daily Growth Brief*');
lines.push('');
lines.push(data.summary || '');
lines.push('');
lines.push('*Top 3 priorities today:*');
(data.priorities||[]).forEach((p,i)=>lines.push(`${i+1}. ${p}`));
lines.push('');
lines.push('*5 content hooks (draft ideas — approve before posting):*');
(data.hooks||[]).forEach((h)=>lines.push(`• ${h}`));
return [{ json: { text: lines.join('\n'), approvalUrl: $('Build Context').item.json.approvalUrl } }];
